TW_TALESDB_AVATAR_DB.getById = function(id) {
  return this.items.find(function(it) { return it.id === id; }) || null;
};
TW_TALESDB_AVATAR_DB.getByName = function(name) {
  if (!name) return null;
  return this.items.find(function(it) { return it.name === name || it.rawName === name; }) || null;
};
